draw:
var pad = 40, x0 = pad, x1 = W - 14, yb = H - 26, yt = 16;
var xmaxDeg = 90, ymax = 1.6;
function X(d) { return x0 + (d / xmaxDeg) * (x1 - x0); }
function Y(v) { return yb - (v / ymax) * (yb - yt); }
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x0, yt); ctx.lineTo(x0, yb); ctx.lineTo(x1, yb); ctx.stroke();
ctx.fillStyle = C.faint;
for (var d = 0; d <= 90; d += 30) {
  ctx.beginPath(); ctx.moveTo(X(d), yb); ctx.lineTo(X(d), yb + 4); ctx.stroke();
  ctx.fillText(d + "°", X(d) - 8, yb + 17);
}
for (var v = 0.5; v <= 1.5001; v += 0.5) {
  ctx.beginPath(); ctx.moveTo(x0 - 4, Y(v)); ctx.lineTo(x0, Y(v)); ctx.stroke();
  ctx.fillText(v.toFixed(1), 8, Y(v) + 4);
}

function curve(f, color, dash) {
  ctx.strokeStyle = color; ctx.lineWidth = 1.8;
  ctx.setLineDash(dash);
  ctx.beginPath();
  for (var i = 0; i <= 120; i++) {
    var dd = xmaxDeg * i / 120, r = dd * Math.PI / 180;
    var xx = X(dd), yy = Y(f(r));
    if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
  }
  ctx.stroke();
  ctx.setLineDash([]);
}

curve(function (r) { return r; }, C.faint, [4, 4]);
curve(function (r) { return r - r * r * r / 6; }, C.figure, [2, 3]);
curve(function (r) { return Math.sin(r); }, C.ink, []);

// labels on curves
ctx.fillStyle = C.faint; ctx.fillText("y = θ", X(62), Y(1.20));
ctx.fillStyle = C.figure; ctx.fillText("θ − θ³/6", X(64), Y(0.72));
ctx.fillStyle = C.ink; ctx.fillText("sin θ", X(70), Y(1.02));

// marker at the chosen angle, with a breathing highlight of the gap
var deg = p.theta, rad = deg * Math.PI / 180;
var s = Math.sin(rad);
var xm = X(deg);
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(xm, yt); ctx.lineTo(xm, yb); ctx.stroke();
ctx.setLineDash([]);

var pulse = 1.5 + 1.5 * (0.5 + 0.5 * Math.sin(2 * t));
ctx.strokeStyle = C.accent; ctx.lineWidth = pulse;
ctx.beginPath(); ctx.moveTo(xm, Y(s)); ctx.lineTo(xm, Y(rad)); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(xm, Y(s), 3.5, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(xm, Y(rad), 3.5, 0, 6.2832); ctx.fill();

var err = (rad - s) / s * 100;
out.note = "θ = " + deg.toFixed(0) + "° = " + rad.toFixed(4) +
  " rad,  sin θ = " + s.toFixed(4) +
  ",  error of θ ≈ sin θ: " + err.toFixed(2) + "%";
